import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第三十九卦 蹇 水山蹇 坎上艮下","description":"周易 - 第三十九卦 蹇 水山蹇 坎上艮下","frontmatter":{"title":"第三十九卦 蹇 水山蹇 坎上艮下","description":"周易 - 第三十九卦 蹇 水山蹇 坎上艮下"},"headers":[],"relativePath":"classics/zhouyi/040.md","filePath":"classics/zhouyi/040.md"}'),l={name:"classics/zhouyi/040.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="蹇" tabindex="-1">蹇 <a class="header-anchor" href="#蹇" aria-label="Permalink to “蹇”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>利西南，不利東北；利見大人，貞吉。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>蹇，難也，險在前也。見險而能止，知矣哉！蹇利西南，往得中也；不利東北，其道窮也。利見大人，往有功也。當位貞吉，以正邦也。蹇之時用大矣哉！</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>山上有水，蹇；君子以反身修德。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>往蹇，來譽。象曰：往蹇來譽，宜待也。</p><h3 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h3><p>王臣蹇蹇，匪躬之故。象曰：王臣蹇蹇，終無尤也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>往蹇來反。象曰：往蹇來反，內喜之也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>往蹇來連。象曰：往蹇來連，當位實也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>大蹇朋來。象曰：大蹇朋來，以中節也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>往蹇來碩，吉；利見大人。象曰：往蹇來碩，志在內也。利見大人，以從貴也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
